cat > /tmp/opencode/sqlsnap/main.go <<'EOF'
package main

import (
	"context"
	"database/sql"
	"fmt"
	"net/url"
	"os"
	"path/filepath"

	_ "modernc.org/sqlite"
)

func dsn(path string) string {
	v := url.Values{}
	v.Set("_busy_timeout", "5000")
	v.Set("_foreign_keys", "on")
	v.Set("_journal_mode", "WAL")
	v.Set("_synchronous", "FULL")
	v.Set("_txlock", "immediate")
	return (&url.URL{Scheme: "file", Path: path, RawQuery: v.Encode()}).String()
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func main() {
	dir, _ := os.MkdirTemp("", "dryrun")
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "run-control.db")

	// Simulate a workspace where the server already created run-control.db
	// (runcontrol tables only, no product tables yet).
	boot, err := sql.Open("sqlite", dsn(path))
	must(err)
	must(boot.Close())

	// --dry-run path: productstate.Existing -> open -> createSchema.
	db, err := sql.Open("sqlite", dsn(path))
	must(err)
	_, err = db.ExecContext(context.Background(), `
CREATE TABLE IF NOT EXISTS product_states (
  kind TEXT NOT NULL, scope TEXT NOT NULL, schema_version INTEGER NOT NULL,
  header_json BLOB NOT NULL, header_hash BLOB NOT NULL, updated_at TEXT NOT NULL,
  PRIMARY KEY (kind, scope)
);
CREATE TABLE IF NOT EXISTS product_state_items (
  kind TEXT NOT NULL, scope TEXT NOT NULL, item_key TEXT NOT NULL, ordinal INTEGER NOT NULL,
  payload_json BLOB NOT NULL, payload_hash BLOB NOT NULL,
  PRIMARY KEY (kind, scope, item_key),
  FOREIGN KEY (kind, scope) REFERENCES product_states(kind, scope) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS product_state_items_order ON product_state_items(kind, scope, ordinal);`)
	must(err)

	rows, err := db.Query(`SELECT name FROM sqlite_master WHERE type IN ('table','index') AND name LIKE 'product%'`)
	must(err)
	for rows.Next() {
		var name string
		must(rows.Scan(&name))
		fmt.Println("schema object created by dry-run probe:", name)
	}
	rows.Close()
	db.Close()

	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
		fmt.Println("file in .ultraplan after dry-run probe:", e.Name())
	}
}
EOF
